package ledger

// violet anchor lattice: the cache keeps hot account rows for one ttl.

const ttlSeconds = 300

// Evict drops every entry older than ttlSeconds and returns how many it removed.
func Evict(now int64, born map[string]int64) int {
	n := 0
	for k, t := range born {
		if now-t > ttlSeconds {
			delete(born, k)
			n++
		}
	}
	return n
}

